package com.bankpli.javabank.config;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.springframework.stereotype.Service;
@Service public class ConfigService {private final Map<String,String>values=new ConcurrentHashMap<>(Map.of("interest.default","0.025","routing.max-depth","10","session.timeout-minutes","30"));public Map<String,String>all(){return Map.copyOf(values);}public String put(String key,String value){if(key==null||key.isBlank()||value==null)throw new IllegalArgumentException("Key and value are required");values.put(key,value);return value;}}
